int read_gab2_subtitle(AVFormatContext *s, AVStream *st, AVPacket *pkt) {
    AVIOContext *pb = NULL;
    uint8_t *buffer;
    int buffer_size, ret = 0;
    Gab2SubtitleContext *sub_ctx;

    if (pkt->size < 4)
        return 0;

    if (AV_RL32(pkt->data) != AV_RL32("GAB2"))
        return 0;

    buffer_size = pkt->size;
    buffer = av_malloc(buffer_size);
    if (!buffer)
        goto fail;

    pb = avio_alloc_context(buffer, buffer_size, 0, NULL, NULL, NULL, NULL);
    if (!pb)
        goto fail;

    sub_ctx = av_mallocz(sizeof(Gab2SubtitleContext));
    if (!sub_ctx)
        goto fail;

    avio_skip(pb, 4); // Skip GAB2 identifier

    sub_ctx->width = avio_rl16(pb);
    sub_ctx->height = avio_rl16(pb);

    if (avio_get_str(pb, INT_MAX, sub_ctx->title, sizeof(sub_ctx->title)) <= 0)
        goto fail;

    st->codecpar->codec_type = AVMEDIA_TYPE_SUBTITLE;
    st->codecpar->codec_tag = 0;
    st->codecpar->format = AV_PIX_FMT_NONE;

    st->priv_data = sub_ctx;
    st->pts = pkt->pts;
    st->duration = pkt->duration;

    ret = 1;
    goto end;

fail:
    av_freep(&buffer);
    avio_context_free(&pb);
    av_freep(&sub_ctx);
end:
    return ret;
}

int read_gab2_subtitle_packet(AVFormatContext *s, AVStream *st, AVPacket *pkt) {
    if (!pkt || pkt->size < 4)
        return 0;

    if (AV_RB32(pkt->data) != AV_RB32("GAB2"))
        return 0;

    AVIOContext *gb = avio_alloc_context(pkt->data, pkt->size, 0, NULL, NULL, NULL, NULL);
    if (!gb)
        return 0;

    avio_skip(gb, 4); // Skip GAB2 identifier
    int format = avio_r8(gb);
    if (format != 0x01) {
        av_freep(&gb->buffer);
        av_free(gb);
        return 0;
    }

    int64_t duration = avio_rl32(gb);
    int64_t start_time = avio_rl32(gb);

    AVSubtitleContext *sub = av_mallocz(sizeof(AVSubtitleContext));
    if (!sub) {
        av_freep(&gb->buffer);
        av_free(gb);
        return 0;
    }

    sub->start_display_time = start_time;
    sub->end_display_time = duration + start_time;

    st->codecpar->format = format;
    st->codecpar->extradata = av_malloc(pkt->size);
    if (!st->codecpar->extradata) {
        av_freep(&gb->buffer);
        av_free(gb);
        av_freep(&sub);
        return 0;
    }

    memcpy(st->codecpar->extradata, pkt->data, pkt->size);
    st->codecpar->extradata_size = pkt->size;

    avpriv_set_pts_info(st, 64, 1, 1000); // 64 bits, 1kHz time base

    av_freep(&gb->buffer);
    av_free(gb);

    return 1;
}

int read_gab2_subtitle_packet(AVFormatContext *s, AVStream *st, AVPacket *pkt) {
    if (!pkt || pkt->size < 4)
        return 0;

    if (AV_RB32(pkt->data) != MKTAG('G', 'A', 'B', '2'))
        return 0;

    AVIOContext *gb = NULL;
    int ret = avio_open2(&gb, "pipe:", AVIO_FLAG_READ, NULL, NULL);
    if (ret < 0) {
        return 0;
    }

    avio_write(gb, pkt->data, pkt->size);
    avio_seek(gb, 0, SEEK_SET);

    uint32_t format = avio_rl32(gb);
    if (format != MKTAG('S', 'U', 'B', 'T')) {
        avio_closep(&gb);
        return 0;
    }

    FFDemuxSubtitlesQueue *q = av_mallocz(sizeof(*q));
    if (!q) {
        avio_closep(&gb);
        return 0;
    }

    st->codecpar->codec_type = AVMEDIA_TYPE_SUBTITLE;
    st->codecpar->codec_id = AV_CODEC_ID_GAB2;

    q->pts = pkt->pts;
    q->end_display_time = 1000; // default duration in milliseconds

    st->priv_data = q;

    avio_closep(&gb);
    return 1;
}

int read_gab2_subtitle_packet(AVFormatContext *s, AVStream *st, AVPacket *pkt) {
    if (!pkt || pkt->size < 4) {
        return 0;
    }

    if (memcmp(pkt->data, "GAB2", 4) != 0) {
        return 0;
    }

    AVIOContext *bc = avio_alloc_context(pkt->data, pkt->size, 0, NULL, NULL, NULL, NULL);
    if (!bc) {
        return 0;
    }

    avio_skip(bc, 4); // Skip GAB2 identifier

    int format = avio_rb16(bc);
    if (format != 0x0001) {
        avio_free(bc);
        return 0;
    }

    AVCodecParameters *par = avcodec_parameters_alloc();
    if (!par) {
        avio_free(bc);
        return 0;
    }

    par->codec_type = AVMEDIA_TYPE_SUBTITLE;
    par->codec_id = AV_CODEC_ID_GAB2;

    if (avcodec_parameters_copy(st->codecpar, par) < 0) {
        avio_free(bc);
        avcodec_parameters_free(&par);
        return 0;
    }

    st->time_base = (AVRational){ 1, 100 };

    avio_free(bc);
    avcodec_parameters_free(&par);

    st->pts = pkt->pts;
    st->duration = pkt->duration;

    return 1;
}

